{
  "name": "惠普 6632B 系统直流电源",
  "name_en": "HP 6632B System DC Power Supply",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 6632B 是一台可编程系统直流电源，输出范围约为 0–20 V、0–5 A，具备精密低电流测量和低输出噪声特性。它常用于为实验样品或电子电路稳定供电，并在自动化测试中执行受触发的电压、电流和保护相关测试。",
  "description_en": "The HP 6632B is a programmable system DC power supply rated for about 0–20 V and 0–5 A, with precision low-current measurement and low output noise. It is commonly used to provide stable power to devices or circuits under test and to perform triggered voltage, current, and protection-related tests in automated lab setups.",
  "tag_hints": [
    "DC power supply",
    "programmable power supply",
    "low-noise output",
    "precision current measurement",
    "triggered output testing",
    "automated test system"
  ],
  "actions": [
    {
      "action_name": "auto-abort_output_trigger",
      "description": "将输出触发系统设为闲置状态。",
      "description_en": "Set the output trigger system to the idle state."
    },
    {
      "action_name": "auto-check_error_queue",
      "description": "检查并清除错误队列。",
      "description_en": "Check and clear the error queue."
    },
    {
      "action_name": "auto-current_sense_range",
      "description": "获取/设置电流检测量程。",
      "description_en": "Get/set the current sense range."
    },
    {
      "action_name": "auto-current_trigger",
      "description": "获取/设置触发电流值。",
      "description_en": "Get/set the trigger current value."
    },
    {
      "action_name": "auto-digital_data",
      "description": "获取/设置数字接口数据。",
      "description_en": "Get/set the digital data."
    },
    {
      "action_name": "auto-digital_function",
      "description": "获取/设置数字接口功能。",
      "description_en": "Get/set the digital function."
    },
    {
      "action_name": "auto-display_brightness",
      "description": "获取/设置显示屏亮度。",
      "description_en": "Get/set display brightness."
    },
    {
      "action_name": "auto-display_contrast",
      "description": "获取/设置显示屏对比度。",
      "description_en": "Get/set display contrast."
    },
    {
      "action_name": "auto-init_output_continuous",
      "description": "设置连续输出初始化模式。",
      "description_en": "Set continuous output initiation mode."
    },
    {
      "action_name": "auto-init_output_trigger",
      "description": "将输出触发系统置于已启动状态，等待下一次触发。",
      "description_en": "Set the output trigger system to the initiated state, ready for the next trigger."
    },
    {
      "action_name": "auto-line_frequency",
      "description": "获取/设置线路频率。",
      "description_en": "Get/set line frequency."
    },
    {
      "action_name": "auto-output_dfi",
      "description": "获取/设置 DFI 输出。",
      "description_en": "Get/set the DFI output."
    },
    {
      "action_name": "auto-output_dfi_source",
      "description": "获取/设置 DFI 输出源。",
      "description_en": "Get/set the DFI output source."
    },
    {
      "action_name": "auto-output_protection_delay",
      "description": "获取/设置输出保护延时。",
      "description_en": "Get/set the output protection delay."
    },
    {
      "action_name": "auto-output_remote_inhibit",
      "description": "获取/设置远程禁止输出功能。",
      "description_en": "Get/set the remote inhibit setting."
    },
    {
      "action_name": "auto-sense_sweep_interval",
      "description": "获取/设置测量扫描间隔。",
      "description_en": "Get/set the sense sweep interval."
    },
    {
      "action_name": "auto-sense_sweep_points",
      "description": "获取/设置测量扫描点数。",
      "description_en": "Get/set the number of sense sweep points."
    },
    {
      "action_name": "auto-sense_window",
      "description": "获取/设置测量窗口。",
      "description_en": "Get/set the sensing window."
    },
    {
      "action_name": "auto-voltage_trigger",
      "description": "获取/设置触发电压值。",
      "description_en": "Get/set the trigger voltage value."
    }
  ]
}

